// All app text in 3 languages. Add a key here, then use t("key") in the app.
// Kurdish comes in two separate dialects, each a full language of its own here: Sorani (ckb) and Badini (kmr,
// Bahdini Kurmanji written in Arabic script as in Duhok). They are never mixed — every text has its own version.
export const LANGS = [
  { id: "ckb", name: "کوردی سۆرانی", dir: "rtl" },
  { id: "kmr", name: "کوردی بادینی", dir: "rtl" },
  { id: "ar", name: "العربية", dir: "rtl" },
  { id: "en", name: "English", dir: "ltr" },
];

export const dirOf = (lang) => (LANGS.find((l) => l.id === lang) || LANGS[0]).dir;

