  zipStep3: { ckb: "دوو جار کلیک لە index.html بکە. ئەپەکەت دەکرێتەوە ✅ بۆ ئایکۆن لەسەر دێسکتۆپ: کلیکی ڕاست لە index.html ← Send to ← Desktop.", kmr: "دوو جاران کلیک ل سەر index.html بکە. ئەپێ تە ڤەدبیت ✅ بۆ ئایکۆنێ ل سەر دێسکتۆپ: کلیکا ڕاست ل سەر index.html ← Send to ← Desktop.", ar: "انقر مرتين على index.html فيفتح تطبيقك ✅ ولأيقونة على سطح المكتب: انقر بزر الفأرة الأيمن على index.html ← Send to ← Desktop.", en: "Double-click index.html — your app opens ✅ For a desktop icon: right-click index.html → Send to → Desktop." },
  zipPhoneNote: { ckb: "مۆبایل ناتوانێت فایلی ZIP بکاتەوە. بۆ مۆبایل دوگمەی «دانان لەسەر شاشە» بەکاربهێنە.", kmr: "مۆبایل نەشێت فایلا ZIP ڤەکەت. بۆ مۆبایلی دوگمەیا «دانان ل سەر شاشێ» بکاربینە.", ar: "الهاتف لا يفتح ملفات ZIP. استخدم زر «إضافة إلى الشاشة» للهاتف.", en: "Phones can't open ZIP files. On a phone, use \"Add to screen\"." },
  scrIntro: { ckb: "ئەپەکەت لینکی تایبەتی خۆی هەیە. بەم هەنگاوانە دەیکەیت بە ئایکۆنێک لەسەر شاشەکەت، و ڕاستەوخۆ دەکرێتەوە بەبێ AHM AI.", kmr: "ئەپێ تە لینکێ خۆ یێ تایبەت هەیە. ب ڤان هەنگاڤان تو دێ کەیە ئایکۆنەک ل سەر شاشا خۆ، و ڕاستەوخۆ ڤەدبیت بێ AHM AI.", ar: "لتطبيقك رابط خاص. بهذه الخطوات يصبح أيقونة على شاشتك ويفتح مباشرة دون AHM AI.", en: "Your app has its own link. With these steps it becomes an icon on your screen that opens directly, without AHM AI." },
  scrOpen: { ckb: "دوگمەی سەوزی «کردنەوەی ئەپەکەم» دابگرە.", kmr: "ل سەر دوگمەیا کەسک «ڤەکرنا ئەپێ من» کلیک بکە.", ar: "اضغط الزر الأخضر «افتح تطبيقي».", en: "Tap the green \"Open my app\" button." },
  scrIos2: { ckb: "لە Safari دوگمەی بڵاوکردنەوە ⬆️ دابگرە ← Add to Home Screen.", kmr: "د Safari دا ل سەر دوگمەیا بەلاڤکرنێ ⬆️ کلیک بکە ← Add to Home Screen.", ar: "في Safari اضغط زر المشاركة ⬆️ ← Add to Home Screen.", en: "In Safari, tap Share ⬆️ → Add to Home Screen." },
