  scrAnd2: { ckb: "لە Chrome ⋮ دابگرە ← Add to Home screen ← Add. ئایکۆنەکە لەسەر شاشەکەتە ✅", kmr: "د Chrome دا ل سەر ⋮ کلیک بکە ← Add to Home screen ← Add. ئایکۆن ل سەر شاشا تەیە ✅", ar: "في Chrome اضغط ⋮ ← Add to Home screen ← Add. الأيقونة الآن على شاشتك ✅", en: "In Chrome, tap ⋮ → Add to Home screen → Add. The icon is on your screen ✅" },
  scrPc2: { ckb: "لە Chrome ⋮ دابگرە ← Cast, save and share ← Create shortcut.", kmr: "د Chrome دا ل سەر ⋮ کلیک بکە ← Cast, save and share ← Create shortcut.", ar: "في Chrome اضغط ⋮ ← Cast, save and share ← Create shortcut.", en: "In Chrome, click ⋮ → Cast, save and share → Create shortcut." },
  scrPc3: { ckb: "Open as window هەڵبژێرە ← Create. ئایکۆنەکە لەسەر دێسکتۆپە ✅", kmr: "Open as window هەلبژێرە ← Create. ئایکۆن ل سەر دێسکتۆپێیە ✅", ar: "اختر Open as window ← Create. الأيقونة الآن على سطح المكتب ✅", en: "Tick Open as window → Create. The icon is on your desktop ✅" },
  scrOpenBtn: { ckb: "کردنەوەی ئەپەکەم", kmr: "ڤەکرنا ئەپێ من", ar: "افتح تطبيقي", en: "Open my app" },
  scrNote: { ckb: "ئەگەر دواتر ئەپەکە بگۆڕیت، دووبارە «دانان لەسەر شاشە» دابگرە؛ هەمان ئایکۆن نوێ دەبێتەوە. لە مۆبایل، ئەو زانیارییانەی ئەپەکە پاشەکەوتیان دەکات دوای داخستن دەسڕێنەوە؛ بۆ پاشەکەوتی هەمیشەیی ZIP لە کۆمپیوتەر بەکاربهێنە.", kmr: "ئەگەر پاشان تە ئەپ گوهۆڕی، دووبارە ل سەر «دانان ل سەر شاشێ» کلیک بکە؛ هەمان ئایکۆن نوو دبیت. ل سەر مۆبایلی، ئەو پێزانینێن ئەپ پاشکەفت دکەت پشتی گرتنێ ژێدچن؛ بۆ پاشکەفتکرنا هەردەمی ZIP ل سەر کۆمپیوتەری بکاربینە.", ar: "إذا عدّلت التطبيق لاحقاً، اضغط «إضافة إلى الشاشة» مجدداً؛ تتحدّث نفس الأيقونة. على الهاتف تُمسح البيانات التي يحفظها التطبيق بعد إغلاقه؛ للحفظ الدائم استخدم ZIP على الكمبيوتر.", en: "If you change the app later, tap \"Add to screen\" again — the same icon updates. On phones, data the app saves is cleared when it closes; for permanent saving use the ZIP on a computer." },
