  a2Ios2: { ckb: "لیستەکە بەرەو سەرەوە ڕابکێشە و «Add to Home Screen» ➕ دابگرە.", kmr: "لیستێ بەرەڤ سەری ڕاکێشە و ل سەر «Add to Home Screen» ➕ کلیک بکە.", ar: "مرّر للأسفل واضغط «إضافة إلى الشاشة الرئيسية» ➕.", en: "Scroll down and tap “Add to Home Screen” ➕." },
  a2Ios3: { ckb: "لە سەرەوە «Add» دابگرە ✅ — تەواو! ئایکۆنی AHM AI لەسەر شاشەکەتە.", kmr: "ل سەری ل سەر «Add» کلیک بکە ✅ — ب دوماهی هات! ئایکۆنا AHM AI ل سەر شاشا تەیە.", ar: "اضغط «إضافة» في الأعلى ✅ — انتهى! أيقونة AHM AI على شاشتك.", en: "Tap “Add” at the top ✅ — done! The AHM AI icon is on your screen." },
  a2And1: { ckb: "لە سەرەوە دوگمەی ⋮ (سێ خاڵەکە) دابگرە.", kmr: "ل سەری ل سەر دوگمەیا ⋮ (سێ خال) کلیک بکە.", ar: "اضغط ⋮ (النقاط الثلاث) في الأعلى.", en: "Tap ⋮ (three dots) at the top." },
  a2And2: { ckb: "«Install app» یان «Add to Home screen» دابگرە.", kmr: "ل سەر «Install app» یان «Add to Home screen» کلیک بکە.", ar: "اضغط «تثبيت التطبيق» أو «إضافة إلى الشاشة الرئيسية».", en: "Tap “Install app” or “Add to Home screen”." },
  a2And3: { ckb: "«Install» دابگرە ✅", kmr: "ل سەر «Install» کلیک بکە ✅", ar: "اضغط «تثبيت» ✅", en: "Tap “Install” ✅" },
