export function makeT(lang) {
  return (key) => {
    const v = T[key];
    if (!v) return key;
    // Badini never falls back to Sorani (the two dialects must not mix); English is the neutral fallback.
    return v[lang] ?? (lang === "kmr" ? v.en ?? v.ckb : v.ckb);
  };
}

// Which language a message is written in — so the whole app can follow the language the user speaks.
// Kurdish and Arabic share letters, so the letters only one of them uses decide; Latin text counts as English
// only when it clearly is English (many people write Kurdish in Latin letters: "chon englizi fer bm").
const KU_LETTERS = /[ڕڵێۆەڤ]/g;
const AR_LETTERS = /[ةىيكأإآؤثذضظ]/g;
const EN_WORDS = new Set("the is are was were what how why when where who which can could would should will you your i my me we our they it this that these those and or but to of in on for with about please make write tell give show do does did have has a an not no yes hello hi thanks thank".split(" "));
const KU_LATIN = new Set("bka bkay bkayt bkam bkat bkn chon chya chi chy awa ama aw la ba bo xo xot esa esta bash zor nya niya haya mn min to pim pem bli blei drwst drust chak kurd kurdy kurdi bas basy amro sbay dway pish pash lagal lagall ka chawa wak waku hamu kam zyatr xera xawa bm bkm bkem chbkm chbkam shty shtek shtik hich hech xom xoy nazanm dazanm bzanm krd krdm kra dabe dabet abe abet bika bike slaw spas".split(" "));
// Sorani and Badini share the script and many words, so only words typical of ONE dialect decide which it is.
// Badini (Duhok): ئەز، ئەڤ، نوکە، چاوا، گەلەک، تشت، ژ/ل/د/ب as separate words, د+verb (دکەم)…
// Sorani: ئێستا، چۆن، زۆر، هەموو، شت، لە، لەگەڵ، دە+verb (دەکەم)، ڵ…
const KMR_WORDS = new Set("ئەز ئەڤ ئەڤە ئەڤێ ئەڤی ڤێ ڤی ڤان ڤێرە نوکە چاوا چاوانی گەلەک تشت تشتەک تشتەکی پەیڤ پەیڤا بێژە دبێژیت دبێژم هەمی ژ ل د ب دگەل هیڤیە هیڤی دڤێت تە کیژ کیژان کیڤە کەنگی نینە نینن ئەڤرۆ سوبەهی دوهی پسیار پسیارا بەرسڤ بەرسڤا یێ یا یێن هندێ ژبەر باخڤە دئاخڤیت سلاڤ سپاس مە هەوە وان وی وێ ژی دێ".split(" "));
const CKB_WORDS = new Set("ئێستا چۆن چۆنی زۆر هەموو شت شتێک وشە وشەی بڵێ لە لەگەڵ تکایە دەمەوێت دەتەوێت ئەمە نییە نیە قسە سوپاس سڵاو ئەمڕۆ سبەی دوێنێ پرسیار پرسیارێک وەڵام وەڵامی بەڵام بۆیە کوێ کەی ئێمە ئێوە منیش تۆ".split(" "));
const KMR_LATIN = new Set("ez ezê eze tu ev eva eve niha nuka nooka gelek galak gallak tisht tişt tsht hemi hemî ji li di bi dixwazim dxwazm dixwazi dkm dikim bêje bezhe bizhe cawa çawa chawan chawani spas silav slav hiviye".split(" "));
function kuDialect(s, cur) {
  const words = s.split(/[\s،.؟?!:؛()«»"'\-—…/]+/).filter(Boolean);
  let k = 0, c = 0;
  for (const w of words) {
    if (KMR_WORDS.has(w)) k++;
    if (CKB_WORDS.has(w)) c++;
    if (/^د(?!ە)[کبچزڕنخگلڤشتمپ]/.test(w) && w.length > 2) k += 0.5; // دکەم، دچم، دزانم — Badini present tense
    if (/^دە[کبچزڕنخگلشتمپ]/.test(w) && w.length > 3) c += 0.5;       // دەکەم، دەچم — Sorani present tense
  }
  c += Math.min(2, (s.match(/ڵ/g) || []).length * 0.5); // ڵ is common in Sorani, rare in Badini
  if (k >= 2 && k >= c * 2) return "kmr";
  if (c >= 2 && c >= k * 2) return "ckb";
  return cur === "kmr" || cur === "ckb" ? cur : "ckb"; // unclear: keep the Kurdish dialect already chosen
}
export function detectLang(text, cur) {
  const s = String(text || "").slice(0, 600);
  const arabicScript = (s.match(/[؀-ۿ]/g) || []).length;
  if (arabicScript >= 6) {
    const ku = (s.match(KU_LETTERS) || []).length, ar = (s.match(AR_LETTERS) || []).length;
    if (ku >= 1 && ku * 3 >= ar) return kuDialect(s, cur);
    if (ar >= 2 && ku === 0) return "ar";
    return null;
  }
  const words = s.toLowerCase().match(/[a-zçêîşû']+/g) || [];
  if (words.length < 3 || arabicScript) return null;
  const en = words.filter((w) => EN_WORDS.has(w)).length, kl = words.filter((w) => KU_LATIN.has(w)).length;
  const bl = words.filter((w) => KMR_LATIN.has(w)).length;
  if (bl >= 2 && bl >= kl && bl > en) return "kmr"; // Badini written in Latin letters
  if (kl >= 2 && kl > en) return cur === "kmr" && bl ? "kmr" : "ckb"; // Kurdish written in Latin letters
  return en >= 2 && en >= kl * 3 && en / words.length >= 0.25 ? "en" : null;
}
